275	            throw new ResponseStatusException(HttpStatus.CONFLICT,
276	                    "The amount split off must be more than 0.00 and less than " + claim.getAmount().toPlainString());
277	        }
278	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
279	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
280	        Rollup.Figures before = rollup.figures(sheetId);
281	        claim.setAmount(claim.getAmount().subtract(amount));
282	        claim.unbind();
283	        Claim part = new Claim(sheetId, owner.getId(), amount, claim.getDate(), claim.getNote(), null);
284	        sheets.load(sheetId, user);
285	        part.setDueBy(claim.getDate().plusDays(
286	                sheets.settings(sheetId).termsFor(owner.getTerms(), owner.gradeOn(claim.getDate()), claim.getDate())));
287	        part.setSplitFrom(claim.getShownNumber());
288	        giveNumber(sheetId, part);
289	        part.setOpenedBy(user);
290	        part.setStatus(ClaimStatus.OPEN);
291	        log(sheetId, user, part, owner);
292	        claims.saveAndFlush(part);
293	        events.publishEvent(new ClaimSplit(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
294	                claim.getShownNumber(), part.getShownNumber()));
295	        events.publishEvent(new ClaimChanged("CLAIM_OPENED", sheetId, user, owner.getName(), part.getAmount(),
296	                part.getDate(), part.getShownNumber(), null));
297	        rollup.changed(sheetId, user, before);
298	        return owner.getId();
299	    }
300	
301	    /**
302	     * Add a proof to a claim, raising its proofs count by one. A SETTLED or VOID claim, or a claim dated
303	     * inside a closed period, is refused and nothing changes. Returns the person it belongs to.
304	     */
305	    @Transactional
306	    public long addProof(String sheetId, String user, long claimId) {
307	        Claim claim = claim(sheetId, claimId);
308	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
309	            throw new ResponseStatusException(HttpStatus.CONFLICT,
310	                    "A " + claim.getStatus() + " claim cannot take a proof");
311	        }
312	        claim.addProof();
313	        claims.flush();
314	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
315	        events.publishEvent(new ClaimProofAdded(sheetId, user, person, claim.getAmount(), claim.getDate(),
316	                claim.getShownNumber(), claim.getProofs()));
317	        return claim.getPersonId();
318	    }
319	
320	    /**
321	     * Refuse settling or approving a claim with no proof whose due (null: n/a) is above the sheet's proof
322	     * threshold in force on the claim's date.
323	     */
324	    private void requireProof(String sheetId, Claim claim, BigDecimal due) {
325	        if (due == null || claim.getProofs() > 0) {
326	            return;
327	        }
328	        BigDecimal threshold = sheets.settings(sheetId).proofThreshold(claim.getDate());
329	        if (threshold != null && due.compareTo(threshold) > 0) {
330	            throw new ResponseStatusException(HttpStatus.CONFLICT,
331	                    "A claim with a due above " + threshold.toPlainString() + " needs a proof to be settled");
332	        }
333	    }
334	
335	    /**
336	     * Approve a PENDING claim, settling it with its due fixed now (its live figure, late charge frozen in).
337	     * Only a steward approves, never the user who opened the claim; a claim not PENDING or dated inside a
338	     * closed period is refused and nothing changes. Returns the person it belongs to.
339	     */
340	    @Transactional
341	    public long approve(String sheetId, String user, long claimId) {
342	        Claim claim = pending(sheetId, user, claimId, "approve", "approved");
343	        if (user.equals(claim.getOpenedBy())) {
344	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it");
345	        }
346	        Rollup.Figures before = rollup.figures(sheetId);
347	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
348	        BigDecimal fixed = dueNow(sheetId, claim, owner);
349	        requireProof(sheetId, claim, fixed);
350	        claim.setSettledDue(fixed);
351	        claim.setStatus(ClaimStatus.SETTLED);
352	        log(sheetId, user, claim, owner);
353	        claims.flush();
354	        events.publishEvent(new ClaimChanged("CLAIM_APPROVED", sheetId, user, owner == null ? "" : owner.getName(),
355	                claim.getAmount(), claim.getDate(), claim.getShownNumber(), fixed == null ? "n/a" : fixed.toPlainString()));
356	        watches.notifyWatchers(sheetId, user, owner, claim.getShownNumber());
357	        rollup.changed(sheetId, user, before);
358	        return claim.getPersonId();
359	    }
360	
361	    /**
362	     * Re-settle a SETTLED claim, fixing its due again at the figure it would have today as an OPEN claim bound
363	     * by no statement (today's rates, grades, floor and late charge), and logging it SETTLED again. Only a
364	     * steward re-settles; a claim not SETTLED or dated inside a closed period is refused and nothing changes.
365	     * Returns the person it belongs to.
366	     */
367	    @Transactional
368	    public long resettle(String sheetId, String user, long claimId) {
369	        Claim claim = claim(sheetId, claimId);
370	        if (claim.getStatus() != ClaimStatus.SETTLED) {
371	            throw new ResponseStatusException(HttpStatus.CONFLICT,
372	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can");
373	        }
374	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
375	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can re-settle a claim");
376	        }
377	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
378	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
379	        Rollup.Figures before = rollup.figures(sheetId);
380	        BigDecimal old = claim.getSettledDue();
381	        BigDecimal fixed = Dues.asOpen(claim, owner::gradeOn, rates.table(sheetId));
382	        claim.setSettledDue(fixed);
383	        claim.logStatus(user, sheets.today(sheetId), fixed);
384	        claims.flush();
385	        events.publishEvent(new ClaimResettled(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
386	                claim.getShownNumber(), old, fixed));
387	        watches.notifyWatchers(sheetId, user, owner, claim.getShownNumber());
388	        rollup.changed(sheetId, user, before);
389	        return claim.getPersonId();
390	    }
391	
392	    /**
393	     * Reject a PENDING claim with a reason, putting it back to OPEN (bound again by the last statement if
394	     * that statement counted it). Only a steward rejects; a claim not PENDING or dated inside a closed
395	     * period is refused and nothing changes. Returns the person it belongs to.
396	     */
397	    @Transactional
398	    public long reject(String sheetId, String user, long claimId, String reason) {
399	        Claim claim = pending(sheetId, user, claimId, "reject", "rejected");
400	        Rollup.Figures before = rollup.figures(sheetId);
401	        claim.setStatus(ClaimStatus.OPEN);
402	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
403	        log(sheetId, user, claim, owner);
404	        claims.flush();
405	        String person = owner == null ? "" : owner.getName();
406	        events.publishEvent(new ClaimChanged("CLAIM_REJECTED", sheetId, user, person, claim.getAmount(),
407	                claim.getDate(), claim.getShownNumber(), null, reason));
408	        rollup.changed(sheetId, user, before);
409	        return claim.getPersonId();
410	    }
411	
412	    /**
413	     * A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. The claim keeps its
414	     * number and date, is released from any figure a statement bound it to (live again until its new
415	     * person's next statement), and lists as its new person's newest claim. A settled or voided claim, a
416	     * correction, a claim dated inside a closed period or after the new person's retirement date, or a move
417	     * by a role the sheet's permission matrix does not allow (a steward, unless set) is refused and nothing changes. Returns the people it moved from and to.
418	     */
419	    @Transactional
420	    public long[] reassign(String sheetId, String user, long claimId, long toPersonId) {
421	        Claim claim = claim(sheetId, claimId);
422	        if (!access.allows(sheetId, user, Permission.REASSIGN)) {
423	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Your role may not reassign a claim on this sheet");
424	        }
425	        if (claim.getStatus() != ClaimStatus.DRAFT && claim.getStatus() != ClaimStatus.OPEN
426	                && claim.getStatus() != ClaimStatus.PENDING) {
427	            throw new ResponseStatusException(HttpStatus.CONFLICT,
428	                    "A " + claim.getStatus() + " claim cannot be reassigned");
429	        }
430	        if (claim.isCorrection()) {
431	            throw new ResponseStatusException(HttpStatus.CONFLICT,
432	                    "A correction belongs with the claim it corrects and cannot be reassigned");
433	        }
434	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
435	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
436	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
437	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "Choose a person on the sheet"));
438	        if (from.getId().equals(to.getId())) {
439	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s");
440	        }
441	        requireNotRetired(to, claim.getDate());
442	        Rollup.Figures before = rollup.figures(sheetId);
443	        claim.setPersonId(to.getId());
444	        claim.unbind();
445	        claims.flush();
446	        claims.relist(claim.getId());
447	        events.publishEvent(new ClaimReassigned(sheetId, user, to.getName(), claim.getAmount(), claim.getDate(),
448	                claim.getShownNumber(), from.getName(), to.getName()));
449	        rollup.changed(sheetId, user, before);
450	        return new long[] { from.getId(), to.getId() };
451	    }
452	
453	    /** The PENDING claim a steward is to approve or reject; refused for anyone else or any other claim. */
454	    private Claim pending(String sheetId, String user, long claimId, String action, String done) {
455	        Claim claim = claim(sheetId, claimId);
456	        if (claim.getStatus() != ClaimStatus.PENDING) {
457	            throw new ResponseStatusException(HttpStatus.CONFLICT,
458	                    "A " + claim.getStatus() + " claim cannot be " + done + "; only a PENDING one can");
459	        }
460	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
461	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can " + action + " a claim");
462	        }
463	        return claim;
464	    }
465	
466	    /**
467	     * A SETTLED claim may be voided only by a steward, and only while the sheet's today is no more than
468	     * 7 days after the date its status log records it SETTLED.
469	     */
470	    private void requireVoidableSettled(String sheetId, String user, Claim claim) {
471	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
472	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may void a SETTLED claim");
473	        }
474	        LocalDate settledOn = claim.getLog().stream().filter(l -> l.getStatus() == ClaimStatus.SETTLED)
475	                .map(ClaimLogLine::getOn).reduce((a, b) -> b).orElse(null);
476	        LocalDate today = sheets.today(sheetId);
477	        if (settledOn == null || today.isAfter(settledOn.plusDays(7))) {
478	            throw new ResponseStatusException(HttpStatus.CONFLICT,
479	                    "A SETTLED claim can only be voided within 7 days of its settlement"
480	                            + (settledOn == null ? "" : " (" + settledOn + ")"));
481	        }
482	    }
483	
484	    private Claim claim(String sheetId, long claimId) {
485	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
486	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
487	        periods.requireOpen(sheetId, claim.getDate());
488	        return claim;
489	    }
490	
491	    /** Log the status a claim has just taken, on the sheet's today, with its due as it is now. */
492	    private void log(String sheetId, String user, Claim claim, Person owner) {
493	        BigDecimal due = owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : claim.getSettledDue())
494	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
495	        claim.logStatus(user, sheets.today(sheetId), due);
496	    }
497	
498	    /** The claim's due now, its late charge frozen in, as settling fixes it. */
499	    private BigDecimal dueNow(String sheetId, Claim claim, Person owner) {
500	        return owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : null)
501	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
502	    }
503	
504	    /**
505	     * Give a claim being opened its number: while the sheet's period numbering from is set and the
506	     * sheet's today is on or after it, the next in the period its date falls in (<period name>-<n>), or
507	     * in the sequence of claims in no period (X-<n>); otherwise the next sheet-wide number. Two users
508	     * taking one at the same moment wait on each other, so no number is given twice or skipped.
509	     */
510	    private void giveNumber(String sheetId, Claim claim) {
511	        LocalDate from = sheets.periodNumberingFrom(sheetId);
512	        if (from == null || sheets.today(sheetId).isBefore(from)) {
513	            claim.setNumber(sheets.nextClaimNumber(sheetId));
514	            return;
515	        }
516	        sheetRows.lockById(sheetId);
517	        Period period = periods.list(sheetId).stream().filter(p -> p.contains(claim.getDate()))
518	                .findFirst().orElse(null);
519	        String sequence = period == null ? "X" : "P" + period.getId();
520	        int n = claims.lastInSequence(sheetId, sequence) + 1;
521	        claim.setPeriodNumber(sequence, n, (period == null ? "X" : period.getName()) + "-" + n);
522	    }
523	
524	    /**
525	     * Refuse a correction (a negative amount) that does not name the number of a SETTLED claim of the
526	     * same person, and a claim that is not a correction but names one. Returns the date of the claim a
527	     * correction corrects (its rounding goes by it); null for any other claim.
528	     */
529	    private LocalDate requireCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
530	        if (amount.signum() >= 0) {
531	            if (corrects != null) {
532	                throw new ResponseStatusException(HttpStatus.CONFLICT,
533	                        "Only a correction (a negative amount) names a claim it corrects");
534	            }
535	            return null;
536	        }
537	        if (corrects == null) {
538	            throw new ResponseStatusException(HttpStatus.CONFLICT,
539	                    "A negative amount is a correction; name the number of the settled claim it corrects");
540	        }
541	        return claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
542	                .filter(c -> corrects.equals(c.getShownNumber()) && c.getStatus() == ClaimStatus.SETTLED)
543	                .map(Claim::getDate).findFirst()
544	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
545	                        "Claim " + corrects + " is not a settled claim of this person"));
546	    }
547	
548	    /** Refuse a claim dated after its person's retirement date. */
549	    private static void requireNotRetired(Person person, LocalDate date) {
550	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
551	            throw new ResponseStatusException(HttpStatus.CONFLICT,
552	                    person.getName() + " is retired from " + person.getRetiredFrom()
553	                            + "; a claim cannot be dated after that");
554	        }
555	    }
556	}
